                // Call the configuration handler function
                if (fn(line, data)) {
                    entry_count++;
                }
            }
            fclose(config_file);
        }
    }

    // Check for user-specific configuration file
    if (!config_exclusive_filename || !*config_exclusive_filename) {
        char* home_dir = getenv("HOME");
        if (home_dir) {
            size_t len = strlen(home_dir) + strlen("/.performance.conf") + 1;
            char* user_config_path = malloc(len);
            if (user_config_path) {
                snprintf(user_config_path, len, "%s/.performance.conf", home_dir);
                config_file = fopen(user_config_path, "r");
