#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define CONFIG_SYSTEM "/etc/performance.conf"
#define CONFIG_USER "~/.performance.conf"

int apply_performance_configurations(config_fn_t fn, void* data) {
    int count = 0;
    FILE* file = NULL;

    // Check if an exclusive configuration file is set
    if (config_exclusive_filename != NULL) {
        file = fopen(config_exclusive_filename, "r");
        if (file) {
            char line[1024];
            while (fgets(line, sizeof(line), file)) {
                if (fn(line, data)) {
                    count++;
                }
            }
            fclose(file);
        }
    } else {
        // Read system-wide configuration
        file = fopen(CONFIG_SYSTEM, "r");
        if (file) {
            char line[1024];
            while (fgets(line, sizeof(line), file)) {
                if (fn(line, data)) {
                    count++;
                }
            }
            fclose(file);
        }

        // Read user-specific configuration
        char* home = getenv("HOME");
        if (home) {
            size_t len = strlen(home) + strlen(CONFIG_USER) + 2;
            char* user_config = malloc(len);
            if (user_config) {
                snprintf(user_config, len, "%s/%s", home, CONFIG_USER + 1); // Skip the leading '~'
                file = fopen(user_config, "r");
                if (file) {
                    char line[1024];
                    while (fgets(line, sizeof(line), file)) {
                        if (fn(line, data)) {
                            count++;
                        }
                    }
                    fclose(file);
                }
                free(user_config);
            }
        }
    }

    if (count == 0) {
        return -1;
    }

    return count;
}

int apply_performance_configurations(config_fn_t fn, void *data) {
    int count = 0;
    if (config_exclusive_filename[0] != '\0') {
        FILE *file = fopen(config_exclusive_filename, "r");
        if (file) {
            count += process_config_file(file, fn, data);
            fclose(file);
        }
    } else {
        FILE *system_file = fopen("/etc/performance.conf", "r");
        if (system_file) {
            count += process_config_file(system_file, fn, data);
            fclose(system_file);
        }

        char home_dir[1024];
        if (getenv("HOME", home_dir, sizeof(home_dir))) {
            snprintf(home_dir, sizeof(home_dir), "%s/.performance.conf", home_dir);
