#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int apply_performance_configurations(config_fn_t fn, void* data) {
    int total_entries = 0;
    FILE *file = NULL;

    // Check if an exclusive configuration file is specified
    if (config_exclusive_filename != NULL && config_exclusive_filename[0] != '\0') {
        file = fopen(config_exclusive_filename, "r");
        if (file) {
            char line[1024];
            while (fgets(line, sizeof(line), file)) {
                if (fn(line, data)) {
                    total_entries++;
                }
            }
            fclose(file);
        }
    }

    // Check for system-wide configuration file
    if (!file && access("/etc/performance.conf", R_OK) == 0) {
        file = fopen("/etc/performance.conf", "r");
        if (file) {
            char line[1024];
            while (fgets(line, sizeof(line), file)) {
                if (fn(line, data)) {
                    total_entries++;
                }
            }
            fclose(file);
        }
    }

    // Check for user-specific configuration file
    char *home_dir = getenv("HOME");
    if (!file && home_dir != NULL) {
        char user_config_path[1024];
        snprintf(user_config_path, sizeof(user_config_path), "%s/.performance.conf", home_dir);
        if (access(user_config_path, R_OK) == 0) {
            file = fopen(user_config_path, "r");
            if (file) {
                char line[1024];
                while (fgets(line, sizeof(line), file)) {
                    if (fn(line, data)) {
                        total_entries++;
                    }
                }
                fclose(file);
            }
        }
    }

    // Return -1 if no configuration file was found
    if (total_entries == 0) {
        return -1;
    }

    return total_entries;
}
